head.script:
scwin.onpageload = function () {
    let arr = [];
    for (let i = 0; i < 10; i++) {
        arr.push({ "c1" : "r" + i + "_1", "c2" : "r" + i + "_2", "c3" : "r" + i + "_3" });
    }
    dlt_main.setJSON(arr);
};

// 현재 포커스 위치
scwin.getFocusText = function () {
    let el = document.activeElement;
    if (el && el.tagName === "INPUT" && grd_main.render.contains(el)) {
        return "셀 입력창 유지";
    }
    return "잃음 (" + (el ? el.tagName : "없음") + ")";
};

// F9 : 표시 행 수 3 증가 / ArrowDown : 입력 결과 출력
scwin.grd_main_onkeydown = function (e) {
    if (e.key === "F9") {
        let rowNum = grd_main.getVisibleRowNum() + 3;
        grd_main.setVisibleRowNum(rowNum);
        setTimeout(function () {
            scwin.setReturnValue("[F9] setVisibleRowNum(" + rowNum + ") -> 포커스 : " + scwin.getFocusText());
        }, 300);
    } else if (e.key === "ArrowDown") {
        setTimeout(function () {
            scwin.setReturnValue("[Z 입력 + ↓] 두 번째 행 c1 값 : " + dlt_main.getCellData(1, "c1") + " / 포커스 셀 행 : " + grd_main.getFocusedRowIndex());
        }, 300);
    }
};

// 입력 결과 확인 (↓ 키가 그리드에 전달되지 않는 경우 확인용)
scwin.btn_check_onclick = function (e) {
    scwin.setReturnValue("[입력 결과 확인] 두 번째 행 c1 값 : " + dlt_main.getCellData(1, "c1"));
};

// 리턴 값 초기화
scwin.btn_clear_onclick = function (e) {
    tbx_return.setValue("");
};

// 리턴 값 설정
scwin.setReturnValue = function (strValue) {
    tbx_return.setValue(tbx_return.getValue() + strValue);
    tbx_return.setValue(tbx_return.getValue() + "\n");
};
